<template>
  <div id="app">
    <h1>Plant Flashcards 🌿</h1>

    <!-- Toolbar -->
    <div class="toolbar">
      <button @click="activeView = 'plants'" :class="{ active: activeView === 'plants' }">สมุนไพร</button>
      <button @click="activeView = 'kermits'" :class="{ active: activeView === 'kermits' }">ฤาษี</button>
    </div>

    <!-- Show Search Bar Only for Plants -->
    <div v-if="activeView === 'plants'">
      <!-- Chip Buttons for Name -->
      <div class="chip-container">
        <button 
          v-for="chip in nameChips" 
          :key="chip" 
          @click="addChipToSearch(chip, 'name')" 
          class="chip">
          {{ chip }}
        </button>
      </div>
      
      <!-- Chip Buttons for Taste -->
      <div class="chip-container">
        <button 
          v-for="chip in tasteChips" 
          :key="chip" 
          @click="addChipToSearch(chip, 'taste')" 
          class="chip">
          {{ chip }}
        </button>
      </div>
      
      <!-- Chip Buttons for Benefits -->
      <div class="chip-container">
        <button 
          v-for="chip in benefitsChips" 
          :key="chip" 
          @click="addChipToSearch(chip, 'benefits')" 
          class="chip">
          {{ chip }}
        </button>
      </div>

      <!-- Search Textbox -->
      <input v-model="searchQuery" 
             @input="updateSearchCriteriaFromQuery" 
             placeholder="ค้นหาสมุนไพร..." 
             class="search-bar" />
      <button v-if="searchQuery" @click="clearSearch" class="clear-btn">❌</button>

      <!-- Displaying Filtered Plants -->
      <div class="flashcards">
        <PlantFlashCard v-for="(plant, index) in filteredPlants" :key="index" :plant="plant" />
      </div>
    </div>

    <!-- Displaying Kermits if the active view is 'kermits' -->
    <div class="flashcards" v-if="activeView === 'kermits'">
      <KermitFlashCard v-for="(kermit, index) in kermits" :key="index" :kermit="kermit" />
    </div>
  </div>
</template>

<script>
import PlantFlashCard from "./components/PlantFlashCard.vue";
import KermitFlashCard from "./components/KermitFlashCard.vue";

export default {
  components: { PlantFlashCard, KermitFlashCard },
  data() {
    return {
      plants: [],
      kermits: [],
      activeView: "plants",
      searchQuery: "",
      nameChips: ["*","กระ","กำ", "โกฐ"],
      tasteChips: ["*","ฝาด", "ขม", "หอมเย็น", "เปรี้ยว", "หวาน", "มัน", "เค็ม", "เมาเบื่อ"],
      benefitsChips: ["*","บำรุง", "ลม", "กระดูก", "แก้", "กระษัย", "สมาน"],
      searchCriteria: {
        name: "*",
        taste: "*",
        benefits: "*"
      }
    };
  },
  computed: {
    filteredPlants() {
      const { name, taste, benefits } = this.searchCriteria;

      return this.plants.filter(plant => {
        // Check if the name matches (or if we are ignoring the name)
        const matchesName = (name === "*" || plant.name.toLowerCase().includes(name.toLowerCase()));

        // Check if any part contains both the taste and benefits
        const matchesTasteAndBenefits = plant.parts.some(part => {
          const matchesTaste = (taste === "*" || part.taste.toLowerCase().includes(taste.toLowerCase()));
          const matchesBenefits = (benefits === "*" || part.benefits.some(benefit => benefit.toLowerCase().includes(benefits.toLowerCase())));
          return matchesTaste && matchesBenefits;  // Both taste and benefits must match for this part
        });

        // Return true only if both name and taste+benefits are matched
        return matchesName && matchesTasteAndBenefits;
      });
    }
  },
  methods: {
    addChipToSearch(chip, type) {
      // Set the corresponding search criterion based on the chip type
      this.searchCriteria[type] = chip;
      this.updateSearchQuery();
    },
    updateSearchQuery() {
      // Update the search query based on the selected chips
      const { name, taste, benefits } = this.searchCriteria;
      this.searchQuery = `${name !== "*" ? name : ""} ${taste !== "*" ? taste : ""} ${benefits !== "*" ? benefits : ""}`.trim();
    },
    updateSearchCriteriaFromQuery() {
      // Split search query into parts and update the search criteria
      const queryParts = this.searchQuery.split(" ");
      this.searchCriteria.name = queryParts[0] || "*";
      this.searchCriteria.taste = queryParts[1] || "*";
      this.searchCriteria.benefits = queryParts[2] || "*";
    },
    clearSearch() {
      this.searchQuery = "";
      this.searchCriteria = { name: "*", taste: "*", benefits: "*" };
    },
    async loadHerbsData() {
      try {
        let baseUrl = process.env.NODE_ENV === "production" ? "/ttm-app" : "";
        let url = `${baseUrl}/data.json`;

        const response = await fetch(url);
        if (!response.ok) throw new Error(`Failed to fetch data: ${response.statusText}`);

        const data = await response.json();

        // Update plant image paths
        data.plants.forEach(plant => {
          plant.image = `${baseUrl}/img/plants/${plant.name}.jpg`;
        });

        // Preload Kermit images dynamically
        data.hermits.forEach(kermit => {
          let kermitFolder = `${baseUrl}/img/kermits/${kermit.name}`;
          kermit.images = Array.from({ length: 2 }, (_, i) => `${kermitFolder}/pic${i + 1}.jpg`);
        });

        this.plants = data.plants;
        this.kermits = data.hermits;
      } catch (error) {
        console.error("Error loading data:", error);
      }
    },
  },
  mounted() {
    this.loadHerbsData();
  }
};
</script>

