<template>
  <div class="flashcard" @click="handleCardClick">
    <div class="flashcard-inner" :class="{ flipped }">
      <div class="flashcard-front">
        <h2>{{ plant.name }}</h2>
        <div class="image-container">
          <!-- <img 
            :src="plant.image" 
            alt="plant Image" 
            :class="{ zoomed: isZoomed }" 
            @click.stop="handleImageClick" 
          /> -->
          <span 
            v-if="!isZoomed" 
            class="flip-icon" 
            @click.stop="flipCard"
          >↩️</span>
        </div>
      </div>
      <div class="flashcard-back" @click="flipCard">
        <div class="text-container">
          <p class="part-item"><strong>ชื่อ:</strong>{{ plant.name }}</p>
          <p 
            v-for="(part, index) in plant.parts"
            :key="index"
            class="part-item"
          >
            <strong style="color:#581845">{{ part.part }}</strong> 
            <span v-html="getTasteColor(part.taste)"></span>
            <span>{{ part.benefits.join(' ') }}</span>
          </p>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: ["plant"],
  data() {
    return { 
      flipped: false,
      isZoomed: false
    };
  },
  methods: {
    handleCardClick() {
      if (this.flipped) {
        this.flipped = false;
      }
    },
    handleImageClick() {
      this.isZoomed = !this.isZoomed;
    },
    flipCard() {
      this.flipped = !this.flipped;
    },
     
    getTasteColor(text) {
      const   colorDict = {
      "หอม": "orange",        // รสหอม, รสชาติที่หอมหวาน
      "ฝาด": "brown",         // รสฝาด, รสชาติที่ขมขื่น
      "ขม": "black",          // รสขม
      "เผ็ด": "red",      // รสเผ็ดร้อน
      "เปรี้ยว": "lime",      // รสเปรี้ยว
      "หวาน": "green",        // รสหวาน
      "มัน": "amber",        // รสมัน
      "เค็ม": "blue",         // รสเค็ม
      "เมา": "purple",        // รสเมาเบื่อ
      "สุขุม": "beige",       // รสสุขุม
      "จืด": "gray",          // รสจืด, ไม่มีรสชาติเด่น
      "เฝื่อน": "darkgray",   // รสเฝื่อน, รสชาติที่ขมฝืด
      "ร้อน": "darkred"       // รสร้อน, รสชาติที่ร้อนแรง
      };
	
      const key = Object.keys(colorDict).find(k => text.startsWith(k));
      var result =  key ? colorDict[key] : "blue"; // Default color
      return `<span style="color: ${result}; font-weight: bold;"> (${text}) </span>`
    },
  }
};
</script>

